<?php
namespace App\Livewire\Admin\Suppliers;
use App\Models\Supplier; use Livewire\Component;
class Edit extends Component{public Supplier $supplier;public string $name='';public string $address='';public string $tax_id='';public string $contact_name='';public string $phone='';public string $email='';public string $bank_details='';public function mount():void{abort_unless(auth()->user()->canManageAccountingRecords(),403);foreach(['name','address','tax_id','contact_name','phone','email','bank_details'] as $field)$this->$field=$this->supplier->$field??'';}public function save(){$this->supplier->update($this->validate($this->rules()));session()->flash('success','Supplier updated.');return $this->redirectRoute('admin.suppliers.show',$this->supplier,navigate:true);}private function rules():array{return ['name'=>['required','string','max:255'],'address'=>['nullable','string','max:5000'],'tax_id'=>['nullable','string','max:255'],'contact_name'=>['nullable','string','max:255'],'phone'=>['nullable','string','max:255'],'email'=>['nullable','email','max:255'],'bank_details'=>['nullable','string','max:5000']];}public function render(){return view('livewire.admin.suppliers.form',['heading'=>'Edit supplier','submitLabel'=>'Save changes'])->layout('components.layouts.admin',['title'=>'Edit '.$this->supplier->name]);}}
